//! Hardware status reports generated by MGMT.

use crate::shared::CtlToUi;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Report {
    BatteryLevel(u8),
    UsbConnected(bool),
}

impl Report {
    pub fn packet(self) -> (CtlToUi, u8) {
        match self {
            Self::BatteryLevel(level) => (CtlToUi::BatteryLevel, level),
            Self::UsbConnected(connected) => (CtlToUi::UsbConnected, u8::from(connected)),
        }
    }
}

#[allow(async_fn_in_trait)]
pub trait DeviceMonitor {
    /// Wait for the next hardware status report. Implementations control timing.
    async fn next_report(&mut self) -> Report;
}

/// EV16 has neither battery nor CC monitoring (these pins drive LEDs).
impl DeviceMonitor for () {
    async fn next_report(&mut self) -> Report {
        core::future::pending().await
    }
}

/// USB-C sink attachment detection, assuming direct CC sensing and external 5.1k Rd.
/// Sample every 100 ms; require two consecutive matching readings before reporting.
#[derive(Default)]
pub struct UsbCcDetector {
    state: Option<bool>,
    candidate: Option<bool>,
}

impl UsbCcDetector {
    pub fn state(&self) -> Option<bool> {
        self.state
    }

    pub fn update(&mut self, cc1_mv: u32, cc2_mv: u32) -> Option<bool> {
        // USB-C sink CC levels span 250..2040 mV across all Rp advertisements.
        // Allow measurement margin and hysteresis, while rejecting VCONN/open highs.
        // Source: TI TUSB320LAI datasheet, section 6.5, VUFP_CC_*.
        let range = if self.state == Some(true) {
            150..=2150
        } else {
            200..=2100
        };
        let connected = range.contains(&cc1_mv) || range.contains(&cc2_mv);
        if self.candidate != Some(connected) {
            self.candidate = Some(connected);
            return None;
        }
        if self.state == Some(connected) {
            return None;
        }
        self.state = Some(connected);
        Some(connected)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn either_orientation_and_all_current_advertisements() {
        for mv in [250, 420, 610, 700, 940, 1160, 1310, 1690, 2040] {
            for (cc1, cc2) in [(mv, 0), (0, mv), (mv, 3300)] {
                let mut detector = UsbCcDetector::default();
                assert_eq!(detector.update(cc1, cc2), None);
                assert_eq!(detector.update(cc1, cc2), Some(true));
                assert_eq!(detector.update(cc1, cc2), None);
            }
        }
    }

    #[test]
    fn initial_disconnect_debounce_hysteresis_and_unplug() {
        let mut detector = UsbCcDetector::default();
        assert_eq!(detector.update(0, 0), None);
        assert_eq!(detector.update(0, 0), Some(false));
        assert_eq!(detector.update(420, 0), None); // transient
        assert_eq!(detector.update(0, 0), None);
        assert_eq!(detector.state(), Some(false));
        assert_eq!(detector.update(0, 420), None);
        assert_eq!(detector.update(0, 420), Some(true));
        assert_eq!(detector.update(0, 175), None); // hysteresis
        assert_eq!(detector.update(0, 175), None);
        assert_eq!(detector.state(), Some(true));
        assert_eq!(detector.update(0, 0), None);
        assert_eq!(detector.update(0, 0), Some(false));
        assert_eq!(detector.update(3300, 3300), None);
        assert_eq!(detector.update(3300, 3300), None);
    }

    #[test]
    fn usb_packets_are_binary() {
        assert_eq!(
            Report::UsbConnected(true).packet(),
            (CtlToUi::UsbConnected, 1)
        );
        assert_eq!(
            Report::UsbConnected(false).packet(),
            (CtlToUi::UsbConnected, 0)
        );
    }
}
